sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    if (!current.comments.changes()) {
        return;
    }

    // Get the latest comment from sys_journal_field
    var jf = new GlideRecord('sys_journal_field');
    jf.addQuery('element_id', current.sys_id);
    jf.addQuery('element', 'comments');
    jf.addQuery('name', 'sysapproval_approver');
    jf.orderByDesc('sys_created_on');
    jf.setLimit(1);
    jf.query();

    var latestComment = '';
    if (jf.next()) {
        latestComment = jf.value;
    }

    if (!latestComment) {
        gs.info('No new comment found in sys_journal_field');
        return;
    }

    // Query the custom table record using document_id
    var gr = new GlideRecord('x_1216348_claim_0_claim_details');
    gr.addQuery('sys_id', current.document_id);
    gr.query();

    if (gr.next()) {
        gr.remarks = "Comment from " + current.approver.getDisplayValue() + ": " + latestComment;
        gr.update();
        gs.info('Updated custom record with comment: ' + latestComment);
    } else {
        gs.info('No matching custom record found for document_id: ' + current.document_id);
    }

})(current, previous);
